import Foundation

public enum ArtifactKind: String, Codable, Sendable {
    case application
    case framework
    case bundle
    case xpc
    case plugin
    case appex
    case kext
    case package
    case diskImage
    case systemExtension
    case directory
    case file
}

public struct ArtifactSummary: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64

    public init(path: String, name: String, kind: ArtifactKind, regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64) {
        self.path = path
        self.name = name
        self.kind = kind
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
    }
}

/// One nested packaging unit in a component inventory.
public struct ComponentEntry: Codable, Equatable, Sendable {
    /// Path relative to the inventory root; "." for the root artifact itself.
    public let path: String
    /// Display (last path component) name.
    public let name: String
    public let kind: ArtifactKind
    /// Relative path of the containing component; nil for the root artifact.
    public let parent: String?
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64
    /// Root-relative entries whose metadata could not be read and were excluded from the counts.
    public let unreadableEntries: [String]

    public init(path: String, name: String, kind: ArtifactKind, parent: String?,
                regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64,
                unreadableEntries: [String]) {
        self.path = path
        self.name = name
        self.kind = kind
        self.parent = parent
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
        self.unreadableEntries = unreadableEntries
    }
}

public struct ComponentInventory: Codable, Equatable, Sendable {
    public let artifact: String
    public let components: [ComponentEntry]

    public init(artifact: String, components: [ComponentEntry]) {
        self.artifact = artifact
        self.components = components
    }
}

public enum ArtifactScannerError: Error, LocalizedError, Equatable {
    case missing(String)
    case unreadable(String)

    public var errorDescription: String? {
        switch self {
        case .missing(let path): "Artifact does not exist: \(path)"
        case .unreadable(let path): "Artifact cannot be inspected: \(path)"
        }
    }
}

public struct ArtifactScanner: Sendable {
    public init() {}

    private static let resourceKeys: Set<URLResourceKey> = [
        .isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey, .isHiddenKey
    ]

    // MARK: - scan (flat summary)

    public func scan(_ input: URL) throws -> ArtifactSummary {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }

        let keys: Set<URLResourceKey> = [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey]
        guard let rootValues = try? url.resourceValues(forKeys: keys) else { throw ArtifactScannerError.unreadable(url.path) }
        var regularFiles = rootValues.isRegularFile == true ? 1 : 0
        var symbolicLinks = rootValues.isSymbolicLink == true ? 1 : 0
        var bytes = UInt64(max(rootValues.fileSize ?? 0, 0))

        if rootValues.isDirectory == true {
            guard let enumerator = manager.enumerator(at: url, includingPropertiesForKeys: Array(keys),
                                                      options: [.skipsHiddenFiles, .skipsPackageDescendants]) else {
                throw ArtifactScannerError.unreadable(url.path)
            }
            while let child = enumerator.nextObject() as? URL {
                guard let values = try? child.resourceValues(forKeys: keys) else { continue }
                if values.isSymbolicLink == true { symbolicLinks += 1; continue }
                if values.isRegularFile == true {
                    regularFiles += 1
                    bytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }

        return ArtifactSummary(path: url.path, name: url.lastPathComponent,
                               kind: Self.kind(forPathExtension: url.pathExtension,
                                              isDirectory: rootValues.isDirectory == true),
                               regularFileCount: regularFiles, symbolicLinkCount: symbolicLinks, totalBytes: bytes)
    }

    // MARK: - components (nested inventory)

    public func inventory(_ input: URL) throws -> ComponentInventory {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }
        guard let rootValues = try? url.resourceValues(forKeys: Self.resourceKeys) else {
            throw ArtifactScannerError.unreadable(url.path)
        }

        let rootStats = ComponentStats()
        var rows: [ComponentEntry] = []

        if rootValues.isSymbolicLink == true {
            rootStats.symbolicLinks = 1
        } else if rootValues.isRegularFile == true {
            rootStats.regularFiles = 1
            rootStats.bytes = UInt64(max(rootValues.fileSize ?? 0, 0))
        } else if rootValues.isDirectory == true {
            try walk(url, relativePrefix: ".", owningStats: rootStats, owningComponentPath: ".",
                     rows: &rows, manager: manager, rootDirectory: true)
        }

        let rootEntry = ComponentEntry(
            path: ".", name: url.lastPathComponent,
            kind: Self.kind(forPathExtension: url.pathExtension, isDirectory: rootValues.isDirectory == true),
            parent: nil,
            regularFileCount: rootStats.regularFiles,
            symbolicLinkCount: rootStats.symbolicLinks,
            totalBytes: rootStats.bytes,
            unreadableEntries: rootStats.unreadable
        )
        rows.insert(rootEntry, at: 0)
        return ComponentInventory(artifact: url.path, components: rows)
    }

    /// Mutable accumulator for the counts of one registered component.
    private final class ComponentStats {
        var regularFiles = 0
        var symbolicLinks = 0
        var bytes: UInt64 = 0
        var unreadable: [String] = []
    }

    /// Recursively descends `directory`, accumulating into the stats of the component that owns it.
    /// Recognized packaging directories become their own component rows; bundle-interior and plain
    /// directories are traversed without being registered.
    private func walk(_ directory: URL, relativePrefix: String, owningStats: ComponentStats,
                      owningComponentPath: String, rows: inout [ComponentEntry],
                      manager: FileManager, rootDirectory: Bool) throws {
        let children: [URL]
        do {
            children = try manager.contentsOfDirectory(at: directory,
                                                       includingPropertiesForKeys: Array(Self.resourceKeys))
        } catch {
            if rootDirectory { throw ArtifactScannerError.unreadable(directory.path) }
            owningStats.unreadable.append(relativePrefix)
            return
        }

        // Sort for a fully deterministic inventory regardless of filesystem enumeration order.
        for child in children.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            let name = child.lastPathComponent
            if name.hasPrefix(".") { continue }

            let relativePath = relativePrefix == "." ? name : "\(relativePrefix)/\(name)"
            guard let values = try? child.resourceValues(forKeys: Self.resourceKeys) else {
                owningStats.unreadable.append(relativePath)
                continue
            }
            if values.isHidden == true { continue }

            if values.isSymbolicLink == true {
                // Count the link itself; never descend into (or count) its target.
                owningStats.symbolicLinks += 1
                continue
            }
            if values.isRegularFile == true {
                owningStats.regularFiles += 1
                owningStats.bytes += UInt64(max(values.fileSize ?? 0, 0))
                continue
            }
            guard values.isDirectory == true else { continue }

            if let componentKind = Self.recognizedComponentKind(forPathExtension: child.pathExtension) {
                let childStats = ComponentStats()
                try walk(child, relativePrefix: relativePath, owningStats: childStats,
                         owningComponentPath: relativePath, rows: &rows, manager: manager, rootDirectory: false)
                rows.append(ComponentEntry(
                    path: relativePath, name: name, kind: componentKind, parent: owningComponentPath,
                    regularFileCount: childStats.regularFiles,
                    symbolicLinkCount: childStats.symbolicLinks,
                    totalBytes: childStats.bytes,
                    unreadableEntries: childStats.unreadable
                ))
                // Parent totals include the whole subtree of each child component.
                owningStats.regularFiles += childStats.regularFiles
                owningStats.symbolicLinks += childStats.symbolicLinks
                owningStats.bytes += childStats.bytes
                owningStats.unreadable.append(contentsOf: childStats.unreadable)
            } else {
                // Bundle-interior directories (Contents, Versions, ...) and plain directories
                // are traversed but belong to the owning component.
                try walk(child, relativePrefix: relativePath, owningStats: owningStats,
                         owningComponentPath: owningComponentPath, rows: &rows,
                         manager: manager, rootDirectory: false)
            }
        }
    }

    // MARK: - classification

    /// Kind for extensions that carry packaging/component semantics; nil for ordinary directories.
    static func recognizedComponentKind(forPathExtension pathExtension: String) -> ArtifactKind? {
        switch pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "xpc": .xpc
        case "plugin": .plugin
        case "appex": .appex
        case "kext": .kext
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        case "systemextension": .systemExtension
        default: nil
        }
    }

    static func kind(forPathExtension pathExtension: String, isDirectory: Bool) -> ArtifactKind {
        recognizedComponentKind(forPathExtension: pathExtension) ?? (isDirectory ? .directory : .file)
    }
}

